DROP TABLE IF EXISTS `provider_assessments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `provider_assessments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `provider_id` bigint(20) unsigned NOT NULL,
  `title` varchar(255) NOT NULL,
  `assessment_type` varchar(255) NOT NULL DEFAULT 'qualifying_exam',
  `image_path` varchar(255) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `duration_minutes` smallint(5) unsigned DEFAULT NULL,
  `passing_score` decimal(5,2) DEFAULT NULL,
  `delivery_mode` varchar(255) NOT NULL DEFAULT 'provider_managed',
  `venue` varchar(255) DEFAULT NULL,
  `instructions` text DEFAULT NULL,
  `status` varchar(255) NOT NULL DEFAULT 'active',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `provider_assessments_provider_id_unique` (`provider_id`),
  CONSTRAINT `provider_assessments_provider_id_foreign` FOREIGN KEY (`provider_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

