INSERT INTO `provider_assessments` VALUES (1,2,'Tulay Aral Applicant Screening','screening_assessment','/uploads/scholarship-default.jpg','A short provider-managed screening activity for applicants who pass the initial profile and document review.',30,70.00,'online','Online meeting link supplied to qualified applicants','Prepare a school ID and be ready to discuss your education goals and intended use of the grant.','active','2026-07-19 01:31:38','2026-07-19 01:31:38'),(2,3,'Bukas Kinabukasan STEM Qualifying Activity','qualifying_exam','/uploads/scholarship-default.jpg','A basic science, mathematics, and problem-solving activity for shortlisted STEM Pathways applicants.',60,75.00,'onsite','Bukas Kinabukasan Learning Hub, San Pedro City, Laguna','Bring a school ID, pencil, and the schedule notice issued through the portal.','active','2026-07-19 01:31:38','2026-07-19 01:31:38');
