INSERT INTO `provider_service_purchases` VALUES (1,2,2,'application_cycle_support','Application cycle support',250000,'PHP','paid','in_progress','SP-20260802-2IIWN0FFDO','cs_48093978ec868605db6884b8',NULL,'pi_UsB3MPJHtmojGBvbFsJAjJgT','pay_RY7uoFtLFyTu2H2VjvcKNYGt','gcash',0,'2026-08-02 01:22:25','Our team is preparing the next scholarship application cycle and needs help organizing applicant stages, review ownership, schedules, and notifications before the public deadline.','A clear application workflow with an organized applicant queue, verified schedule details, and applicant notifications ready for the active cycle.','high',1,'2026-09-02 09:00:00','[{\"id\":\"milestone_1\",\"label\":\"Workflow setup review\",\"completed\":true},{\"id\":\"milestone_2\",\"label\":\"Applicant queue organization\",\"completed\":true},{\"id\":\"milestone_3\",\"label\":\"Schedule and notification check\",\"completed\":false}]','2026-08-26 06:00:00','online','Confirm the final applicant stages, review assignments, and notification schedule before the cycle opens.','confirmed','Online coordination meeting confirmed. The private meeting link will be sent to the provider team before the scheduled time.','2026-08-22 04:29:00',1,'2026-08-02 01:23:17',NULL,NULL,NULL,NULL,NULL,NULL,1,'The workflow and applicant queue are organized. The final schedule and notification check is in progress.',NULL,'{\"event_id\":\"evt_8MrZiycMkrajDPqMPvpspbnj\",\"verified_amount\":250000,\"verified_currency\":\"PHP\"}','2026-08-02 01:22:25','2026-08-23 04:29:34'),(2,2,2,'assisted_setup','Assisted program setup',75000,'PHP','paid','completed','SP-20260816-B84UAZTIEG','cs_78225de42fd79abb88dcd9c4',NULL,'pi_GJqEp1dnzKgKmnc2XGfoyQ2p','pay_pjzRXsKw5mxFHCanmaRrQgcF','gcash',0,'2026-08-16 03:24:27','Our organization needed guidance completing its first scholarship program form, defining understandable eligibility rules, and checking the program before submission for admin review.','A complete scholarship program draft 