  `provider_id` bigint(20) unsigned NOT NULL,
  `image_path` varchar(255) DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `category` varchar(255) DEFAULT NULL,
  `program_cycle` varchar(100) DEFAULT NULL,
  `description` text NOT NULL,
  `eligibility` text DEFAULT NULL,
  `eligibility_conditions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`eligibility_conditions`)),
  `eligible_education_levels` text DEFAULT NULL,
  `eligible_courses` text DEFAULT NULL,
  `eligible_school_types` text DEFAULT NULL,
  `eligible_year_levels` text DEFAULT NULL,
  `eligible_locations` text DEFAULT NULL,
  `income_requirement` varchar(255) DEFAULT NULL,
  `location_name` varchar(255) DEFAULT NULL,
  `location_address` text DEFAULT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `requirements` text DEFAULT NULL,
  `optional_requirements` text DEFAULT NULL,
  `post_qualification_requirements` text DEFAULT NULL,
  `handoff_mode` varchar(30) DEFAULT NULL,
  `handoff_instructions` text DEFAULT NULL,
  `handoff_deadline` date DEFAULT NULL,
  `handoff_location_name` varchar(255) DEFAULT NULL,
  `handoff_location_address` varchar(500) DEFAULT NULL,
  `handoff_url` varchar(2048) DEFAULT NULL,
  `review_rubric` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`review_rubric`)),
  `application_questions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`application_questions`)),
  `award_amount` decimal(12,2) DEFAULT NULL,
  `minimum_gwa` decimal(5,2) DEFAULT NULL,
  `minimum_grade_scale` varchar(255) DEFAULT NULL,
  `slots_available` int(10) unsigned DEFAULT NULL,
  `application_mode` varchar(50) DEFAULT NULL,
  `selection_stages` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`selection_stages`)),
  `renewal_policy` text DEFAULT NULL,
  `return_service_contract` text DEFAULT NULL,
  `other_contract_terms` text DEFAULT NULL,
  `contact_email` varchar(255) DEFAULT NULL,
  `contact_number` varchar(30) DEFAULT NULL,
  `application_opens_at` date DEFAULT NULL,
  `expected_results_at` date DEFAULT NULL,
  `official_program_url` varchar(2048) DEFAULT NULL,
  `contact_person` varchar(150) DEFAULT NULL,
  `contact_department` varchar(150) DEFAULT NULL,
  `deadline` date DEFAULT NULL,
  `status` varchar(255) NOT NULL DEFAULT 'draft',
  `views_count` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `provider_terms_accepted_at` timestamp NULL DEFAULT NULL,
  `provider_terms_version` varchar(30) DEFAULT NULL,
  `exam_duration_minutes` smallint(5) unsigned DEFAULT NULL,
  `exam_passing_score` decimal(5,2) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `scholarships_provider_id_status_index` (`provider_id`,`status`),
  KEY `scholarships_deadline_index` (`deadline`),
  CONSTRAINT `scholarships_provider_id_foreign` FOREIGN KEY (`provider_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
