INSERT INTO `scholarships` VALUES (1,2,'/images/programs/tulay-aral-logo.png','Tulay Aral Senior High Support Grant','Financial assistance','School Year 2026-2027','A combined support package for Grade 11 and Grade 12 learners that includes a PHP 10,000 one-time cash grant and school supplies for transportation, learning materials, and connectivity.','Currently enrolled senior high school learner with a general average of at least 80% and a household income within the listed bracket.',NULL,'senior_high_school','Any strand','public\nprivate','Grade 11\nGrade 12',NULL,'PHP 10,000 - 20,000','Tulay Aral Community Desk','Barangay San Isidro, Antipolo City, Rizal',14.6255000,121.1245000,'Certificate of enrollment\nLatest report card or grades\nSchool ID\nProof of income',NULL,'Original certificate of enrollment\nOriginal latest report card\nValid school ID\nProvider formal application form','onsite','If you pass portal pre-screening, bring the listed original documents to the provider. The provider will verify them and explain its formal application process. Portal qualification is not a final scholarship award.','2026-10-04','Tulay Aral Community Desk','Barangay San Isidro, Antipolo City, Rizal',NULL,'[{\"key\":\"eligibility_fit\",\"label\":\"Eligibility fit\",\"weight\":35,\"guidance\":\"Confirm that the applicant meets the program-specific target and restrictions.\"},{\"key\":\"academic_merit\",\"label\":\"Academic merit\",\"weight\":25,\"guidance\":\"Review grades using the scale and education level required by this program.\"},{\"key\":\"financial_need\",\"label\":\"Financial need\",\"weight\":20,\"guidance\":\"Review declared need and supporting income documents where applicable.\"},{\"key\":\"document_quality\",\"label\":\"Document quality\",\"weight\":20,\"guidance\":\"Check whether required documents are complete, readable, current, and valid.\"}]',NULL,10000.00,80.00,'percentage',25,'online','[\"screening\",\"formal_application\",\"decision\"]','One school-year grant. A learner may reapply if still enrolled and the foundation has available funds.',NULL,'Recipients attend one orientation and submit a short end-of-term update on how the assistance was used.','tulayaral@scholarship.test','09171234567','2026-07-22','2026-10-02',NULL,'Mara L. Reyes','Community Scholarship Desk','2026-09-20','published',4,'2026-07-19 01:31:38','2026-09-11 16:43:50','2026-07-22 15:29:20','2026-07-09',NULL,NULL),(2,2,'/images/programs/tulay-aral-logo.png','Tulay Aral College Starter Grant','Community grant','School Year 2026-2027','A college-entry support package that combines a PHP 15,000 one-time cash grant with transition mentoring for enrollment, books, school materials, and first-year preparation.','Incoming first-year college learner with proof of admission, a general average of at least 85%, and availability for a short finalist interview.',NULL,'senior_high_school\ncollege','Any course','state_university\nlocal_college\nprivate','Grade 12\n1st year',NULL,'PHP 10,000 - 20,000','Tulay Aral Community Desk','Barangay San Isidro, Antipolo City, Rizal',14.6255000,121.1245000,'Admission or acceptance letter\nLatest report card or grades\nProof of income\nRecommendation letter',NULL,'Original proof of college admission or enrollment\nOriginal latest report card\nValid school or government ID\nProvider formal application form','onsite','If you pass portal pre-screening, bring the listed original documents to the provider. The provider will verify them and explain its formal application process. Portal qualification is not a final scholarship award.','2026-10-04','Tulay Aral Community Desk','Barangay San Isidro, Antipolo City, Rizal',NULL,'[{\"key\":\"eligibility_fit\",\"label\":\"Eligibility fit\",\"weight\":35,\"guidance\":\"Confirm that the applicant meets the program-specific target and restrictions.\"},{\"key\":\"academic_merit\",\"label\":\"Academic merit\",\"weight\":25,\"guidance\":\"Review grades using the scale and education level required by this program.\"},{\"key\":\"financial_need\",\"label\":\"Financial need\",\"weight\":20,\"guidance\":\"Review declared need and supporting income documents where applicable.\"},{\"key\":\"document_quality\",\"label\":\"Document quality\",\"weight\":20,\"guidance\":\"Check whether required documents are complete, readable, current, and valid.\"}]',NULL,15000.00,85.00,'percentage',15,'onsite','[\"screening\",\"interview\",\"formal_application\",\"decision\"]','This is a one-time college entry grant and is not automatically renewable.',NULL,'Recipients submit proof of enrollment before release and a brief utilization update after the first semester.','tulayaral@scholarship.test','09171234567','2026-07-22','2026-10-06',NULL,'Mara L. Reyes','Community Scholarship Desk','2026-09-20','published',4,'2026-07-19 01:31:38','2026-09-11 16:43:50','2026-07-22 15:29:20','2026-07-09',NULL,NULL),(3,3,'/images/programs/bukas-kinabukasan-logo.png','Bukas Kinabukasan School Essentials Grant','Community grant','School Year 2026-2027','A non-cash support package that provides school supplies, learning materials, and shared learning-device access for elementary and junior high school learners from nearby communities.','Currently enrolled elementary or junior high school learner whose parent or guardian can complete the application.',NULL,'elementary\njunior_high_school','Any','public\nprivate','Grade 1\nGrade 2\nGrade 3\nGrade 4\nGrade 5\nGrade 6\nGrade 7\nGrade 8\nGrade 9\nGrade 10',NULL,'Any','Bukas Kinabukasan Learning Hub','Barangay Nueva, San Pedro City, Laguna',14.3595000,121.0473000,NULL,NULL,'Original learner enrollment record\nLatest report card or grades\nLearner school ID when available\nParent or guardian valid ID\nProvider formal application form signed by the guardian','onsite','If you pass portal pre-screening, bring the listed original documents to the provider. The provider will verify them and explain its formal application process. Portal qualification is not a final scholarship award.','2026-10-04','Bukas Kinabukasan Learning Hub','Barangay Nueva, San Pedro City, Laguna',NULL,'[{\"key\":\"eligibility_fit\",\"label\":\"Eligibility fit\",\"weight\":35,\"guidance\":\"Confirm that the applicant meets the program-specific target and restrictions.\"},{\"key\":\"academic_merit\",\"label\":\"Academic merit\",\"weight\":25,\"guidance\":\"Review grades using the scale and education level required by this program.\"},{\"key\":\"financial_need\",\"label\":\"Financial need\",\"weight\":20,\"guidance\":\"Review declared need and supporting income documents where applicable.\"},{\"key\":\"document_quality\",\"label\":\"Document quality\",\"weight\":20,\"guidance\":\"Check whether required documents are complete, readable, current, and valid.\"}]',NULL,NULL,NULL,NULL,40,'provider_review','[\"screening\",\"formal_application\",\"decision\"]','The non-cash support package covers one school year. Families may apply again during the next intake.',NULL,'A parent or guardian attends the release orientation and confirms receipt of school materials.','bukasfoundation@scholarship.test','09172345678','2026-07-22','2026-09-30',NULL,'Paolo C. Mendoza','Learner Support Office','2026-09-20','published',2,'2026-07-19 01:31:38','2026-09-11 16:43:50','2026-07-22 15:29:20','2026-07-09',NULL,NULL),(4,3,'/images/programs/bukas-kinabukasan-logo.png','Bukas Kinabukasan STEM Pathways Grant','STEM scholarship','School Year 2026-2027','A competitive STEM support package combining a PHP 12,000 learning grant, an enrichment session, and pathway mentoring for senior high school learners preparing for science, engineering, computing, or technology studies.','Grade 11 or Grade 12 STEM learner with at least an 85% general average and availability for a qualifying exam and finalist interview.',NULL,'senior_high_school','STEM','public\nprivate','Grade 11\nGrade 12',NULL,'Any','Bukas Kinabukasan Learning Hub','Barangay Nueva, San Pedro City, Laguna',14.3595000,121.0473000,'Certificate of enrollment\nLatest report card or grades\nSchool ID\nRecommendation letter',NULL,'Original certificate of enrollment\nOriginal latest report card\nValid school ID\nProvider formal application form','onsite','If you pass portal pre-screening, bring the listed original documents to the provider. The provider will verify them and explain its formal application process. Portal qualification is not a final scholarship award.','2026-10-04','Bukas Kinabukasan Learning Hub','Barangay Nueva, San Pedro City, Laguna',NULL,'[{\"key\":\"eligibility_fit\",\"label\":\"Eligibility fit\",\"weight\":35,\"guidance\":\"Confirm that the applicant meets the program-specific target and restrictions.\"},{\"key\":\"academic_merit\",\"label\":\"Academic merit\",\"weight\":25,\"guidance\":\"Review grades using the scale and education level required by this program.\"},{\"key\":\"financial_need\",\"label\":\"Financial need\",\"weight\":20,\"guidance\":\"Review declared need and supporting income documents where applicable.\"},{\"key\":\"document_quality\",\"label\":\"Document quality\",\"weight\":20,\"guidance\":\"Check whether required documents are complete, readable, current, and valid.\"}]',NULL,12000.00,85.00,'percentage',20,'onsite','[\"screening\",\"exam\",\"interview\",\"formal_application\",\"decision\"]','Renewal of the support package for the next school year depends on continued STEM enrollment, satisfactory progress, and available funding.',NULL,'Finalists complete the provider-managed qualifying exam and interview. Recipients join one community learning session during the award period.','bukasfoundation@scholarship.test','09172345678','2026-07-22','2026-10-11',NULL,'Paolo C. Mendoza','STEM Programs Office','2026-09-20','published',9,'2026-07-19 01:31:38','2026-09-11 16:43:50','2026-07-22 15:29:20','2026-07-09',60,75.00);
